(6382828, 945657, 96751, '<td valign="top">Great light.</td>', 'Great light.', '2011-04-11 12:04:53.000000', NULL, 1),
(6382829, 945560, 74911, '<td valign="top">I love the use of tilt in this image... it makes me dizzy if my eyes follow the bridge... I would say the clouds could have been better exposed for an advanced editing challenge... too many blow out highlights. I would have rated this atleast 3 points higher with proper exposure...</td>', 'I love the use of tilt in this image... it makes me dizzy if my eyes follow the bridge... I would say the clouds could have been better exposed for an advanced editing challenge... too many blow out highlights. I would have rated this atleast 3 points higher with proper exposure...', '2011-04-11 12:06:06.000000', NULL, 1),
(6382831, 945691, 74911, '<td valign="top">Great use of tilt.... i do not know if you used shadow/highlight or tonemapping or whatever to balance the highlights and shadows... it looks little overdone for my tastes... otherwise, the image leaves an impact on the viewer...</td>', 'Great use of tilt.... i do not know if you used shadow/highlight or tonemapping or whatever to balance the highlights and shadows... it looks little overdone for my tastes... otherwise, the image leaves an impact on the viewer...', '2011-04-11 12:07:14.000000', NULL, 1),
(6382833, 945708, 74911, '<td valign="top">yes, there is a tilt... your clever title suits the image and implies that the tilt is because of heavy syrup on the right of the frame... this could have been a great example for a "tilted" challenge rather than this challenge, as the "horizon" part is not apparent in the image... just my two cents...</td>', 'yes, there is a tilt... your clever title suits the image and implies that the tilt is because of heavy syrup on the right of the frame... this could have been a great example for a "tilted" challenge rather than this challenge, as the "horizon" part is not apparent in the image... just my two cents...', '2011-04-11 12:09:05.000000', NULL, 1),
(6382835, 945741, 74911, '<td valign="top">I like the grunge effect.... it looks like you have tilted because the challenge asks for it... i mean, i do not get a feel that the tilt is adding to the image in anyways...</td>', 'I like the grunge effect.... it looks like you have tilted because the challenge asks for it... i mean, i do not get a feel that the tilt is adding to the image in anyways...', '2011-04-11 12:10:18.000000', NULL, 1),
(6382838, 945792, 74911, '<td valign="top">Lovely shot... the grass part and its reflection are almost like a painting...</td>', 'Lovely shot... the grass part and its reflection are almost like a painting...', '2011-04-11 12:10:59.000000', NULL, 1),
(6382840, 945789, 74911, '<td valign="top">Great use of leading lines to enhance the tilt...</td>', 'Great use of leading lines to enhance the tilt...', '2011-04-11 12:11:17.000000', NULL, 1),
(6382841, 945757, 74911, '<td valign="top">Great use of tilt.... i like the title too :)</td>', 'Great use of tilt.... i like the title too :)', '2011-04-11 12:11:40.000000', NULL, 1),
(6382842, 945771, 54446, '<td valign="top">This is my top favorite for this challenge.  Great composition and perspective.  It''s the sheer weight of the engine/train defying gravity which makes this work so well.  Hope to see this ribbon.</td>', 'This is my top favorite for this challenge.  Great composition and perspective.  It''s the sheer weight of the engine/train defying gravity which makes this work so well.  Hope to see this ribbon.', '2011-04-11 12:11:41.000000', NULL, 1),
(6382846, 945652, 74911, '<td valign="top">Looks like you have taken inspiration from the 5th or 6th place image from the "Tilted Horizon I" challenge... great results.. lovely use of contrast... the sky seems a little blown out for my tastes...</td>', 'Looks like you have taken inspiration from the 5th or 6th place image from the "Tilted Horizon I" challenge... great results.. lovely use of contrast... the sky seems a little blown out for my tastes...', '2011-04-11 12:12:53.000000', NULL, 1),
(6382847, 945719, 74911, '<td valign="top">Great abstract... the tilt is beautiful...</td>', 'Great abstract... the tilt is beautiful...', '2011-04-11 12:13:09.000000', NULL, 1),
(6382849, 945776, 74911, '<td valign="top">Wow... almost looks like a 3d image.. the bottle almost touches my nose... ;) great use of tilt and distortion...</td>', 'Wow... almost looks like a 3d image.. the bottle almost touches my nose... ;) great use of tilt and distortion...', '2011-04-11 12:13:46.000000', NULL, 1),
(6382852, 945368, 54446, '<td valign="top">Very nicely done.  Good use of tilting the hill country to display a very interesting scene.</td>', 'Very nicely done.  Good use of tilting the hill country to display a very interesting scene.', '2011-04-11 12:14:07.000000', NULL, 1),
(6382856, 945725, 30669, '<td valign="top">OMG!  This is hilarious. I just had to give this a 10. Very creative and love the humor. Love the title.</td>', 'OMG!  This is hilarious. I just had to give this a 10. Very creative and love the humor. Love the title.', '2011-04-11 12:15:22.000000', NULL, 1),
(6382857, 945585, 54446, '<td valign="top">Just right.  Excellent American Avocet image, with an interesting presentation.  9</td>', 'Just right.  Excellent American Avocet image, with an interesting presentation.  9', '2011-04-11 12:16:26.000000', NULL, 1),
(6382861, 945436, 74911, '<td valign="top">lovely use of tilt... and great idea.. that boosts my vote on this image by 3<br/>blowout sky and overexposure... that brings down the vote by 3 - so I give a 6... with better quality the idea and execution would have gotten a 9...</td>', 'lovely use of tilt... and great idea.. that boosts my vote on this image by 3blowout sky and overexposure... that brings down the vote by 3 - so I give a 6... with better quality the idea and execution would have gotten a 9...', '2011-04-11 12:17:16.000000', NULL, 1),
(6382864, 945725, 74911, '<td valign="top">Brilliant... stunning image... clever use of tilt... smart title... actually title conveys the real intent of this image... beautiful... hoping to see this in the front page...</td>', 'Brilliant... stunning image... clever use of tilt... smart title... actually title conveys the real intent of this image... beautiful... hoping to see this in the front page...', '2011-04-11 12:18:18.000000', NULL, 1),
(6382866, 945717, 54446, '<td valign="top">This is great.  A panning shot with cool tilt.  I''m bumping up the score from 9 to 10 this morning based on elegance and degree of difficulty.</td>', 'This is great.  A panning shot with cool tilt.  I''m bumping up the score from 9 to 10 this morning based on elegance and degree of difficulty.', '2011-04-11 12:18:48.000000', NULL, 1),
