(6388086, 945368, 76335, '<td valign="top">Nothing shows off a tilted world like a level line running through your composition. Certainly everything here is going to fall out of the frame and on to my keyboard. (And that little truck too.) Great.</td>', 'Nothing shows off a tilted world like a level line running through your composition. Certainly everything here is going to fall out of the frame and on to my keyboard. (And that little truck too.) Great.', '2011-04-16 17:38:35.000000', NULL, 1),
(6388088, 945456, 76335, '<td valign="top">I appreciate how the sidewalk and one edge of the stop sign form a perpindicular. Don''t think it''s strong enough to hold this together though. Seems like tilt for tilt''s sake more than anything. <br/> <br/>I do, however, very much like the conversion and grainy textures.</td>', 'I appreciate how the sidewalk and one edge of the stop sign form a perpindicular. Don''t think it''s strong enough to hold this together though. Seems like tilt for tilt''s sake more than anything.  I do, however, very much like the conversion and grainy textures.', '2011-04-16 17:40:16.000000', NULL, 1),
(6388089, 945390, 76335, '<td valign="top">Processing feels a bit heavyhanded. I like the directed energy...</td>', 'Processing feels a bit heavyhanded. I like the directed energy...', '2011-04-16 17:41:09.000000', NULL, 1),
(6388091, 945666, 76335, '<td valign="top">Dreamy... Looks like you shot through some up-close vegetation. Has a nice earthy diffusing effect.</td>', 'Dreamy... Looks like you shot through some up-close vegetation. Has a nice earthy diffusing effect.', '2011-04-16 17:42:02.000000', NULL, 1),
(6388092, 945724, 76335, '<td valign="top">So wrong on so many levels: harsh light, tree growing from his head -- and, of course, the tilt. Still it has a blunt, unapologetic sort of appeal to it -- accentuated by that cold stare.</td>', 'So wrong on so many levels: harsh light, tree growing from his head -- and, of course, the tilt. Still it has a blunt, unapologetic sort of appeal to it -- accentuated by that cold stare.', '2011-04-16 17:43:33.000000', NULL, 1),
(6388093, 945726, 76335, '<td valign="top">This makes me smile. Do I have to say more?</td>', 'This makes me smile. Do I have to say more?', '2011-04-16 17:44:30.000000', NULL, 1),
(6388095, 945078, 76335, '<td valign="top">An uninteresting moment made no more interesting by the selective desat or the tilt.</td>', 'An uninteresting moment made no more interesting by the selective desat or the tilt.', '2011-04-16 17:46:07.000000', NULL, 1),
(6388098, 945791, 76335, '<td valign="top">Interesting lines running through this, but not so interesting as to make up for the lack of a stronger focal point.</td>', 'Interesting lines running through this, but not so interesting as to make up for the lack of a stronger focal point.', '2011-04-16 17:47:48.000000', NULL, 1),
(6388099, 945567, 76335, '<td valign="top">Much too sharp. It''s a busy image as it is.</td>', 'Much too sharp. It''s a busy image as it is.', '2011-04-16 17:48:30.000000', NULL, 1),
(6388101, 945267, 76335, '<td valign="top">I''m not seeing how the tilt strengthens or adds interest to this composition.</td>', 'I''m not seeing how the tilt strengthens or adds interest to this composition.', '2011-04-16 17:49:52.000000', NULL, 1),
