(6389202, 945728, 28359, '<td valign="top">Wow...Very cool....Nice finish!!!</td>', 'Wow...Very cool....Nice finish!!!', '2011-04-18 09:39:59.000000', NULL, 0),
(6389204, 944864, 30861, '<td valign="top">Hello, neighbor! I''m pleased to see I''m keeping such good company, me by the sea and you in your beloved mountains. I''m also pleased to see the SEP2 border styles gaining top-10 acceptance. Very nice shot, well done!</td>', 'Hello, neighbor! I''m pleased to see I''m keeping such good company, me by the sea and you in your beloved mountains. I''m also pleased to see the SEP2 border styles gaining top-10 acceptance. Very nice shot, well done!', '2011-04-18 09:42:11.000000', NULL, 0),
(6389234, 945776, 74559, '<td valign="top">Big congrats on your top 10, Larry! What a cool bottle thingy, wonderful image!</td>', 'Big congrats on your top 10, Larry! What a cool bottle thingy, wonderful image!', '2011-04-18 10:06:08.000000', NULL, 0),
(6389236, 945741, 54446, '<td valign="top">Well deserved top 10, Robert.  Love the title.  It was Archimedes who said, "Give me the place to stand, and I shall move the earth."  Your use of the seawall is nicely done.  The processing and use of luminous light in the right places is superb.</td>', 'Well deserved top 10, Robert.  Love the title.  It was Archimedes who said, "Give me the place to stand, and I shall move the earth."  Your use of the seawall is nicely done.  The processing and use of luminous light in the right places is superb.', '2011-04-18 10:07:40.000000', NULL, 0),
(6389288, 945725, 91360, '<td valign="top">amazing concept!love it!</td>', 'amazing concept!love it!', '2011-04-18 10:22:24.000000', NULL, 0),
(6389321, 945306, 2158, '<td valign="top"><table align="center" width="95%"><tr><td><div class="textsm"><b>Originally posted by hernan43:</b></div><hr/><i> Love the reflection. I would have probably tried to keep the lilies out of the shot. Sorry! :-) </i></td></tr></table> <br/> <br/>I totally disagree.  The <strike>lilies</strike> flowers are what makes this shot interesting.</td>', 'Originally posted by hernan43: Love the reflection. I would have probably tried to keep the lilies out of the shot. Sorry! :-)   I totally disagree.  The lilies flowers are what makes this shot interesting.', '2011-04-18 10:38:11.000000', NULL, 0),
(6389342, 945725, 117534, '<td valign="top">I really love that you share your how to''s with us!  AND your crazy dedication!!! Your a Genius !!!  Congratulations on a totaly awesome shot!!!!</td>', 'I really love that you share your how to''s with us!  AND your crazy dedication!!! Your a Genius !!!  Congratulations on a totaly awesome shot!!!!', '2011-04-18 11:06:15.000000', NULL, 0),
