INSERT INTO comments ("id", "image_id", "commenter_id", "raw_comment", "comment", "date", "edited", "made_during_challenge") VALUES
(6389378, 945436, 66515, '<td valign="top">I would say, yes, the sky was blown out. I wouldn''t say that''s a complete problem though. The overall scene, however, is a little on the bright side. Of course your subject is properly exposed but everything else is a little over exposed. Judging from the shadow it appears you were shooting into the sun. If possible I would shoot from the other direction so you have the sun behind you.</td>', 'I would say, yes, the sky was blown out. I wouldn''t say that''s a complete problem though. The overall scene, however, is a little on the bright side. Of course your subject is properly exposed but everything else is a little over exposed. Judging from the shadow it appears you were shooting into the sun. If possible I would shoot from the other direction so you have the sun behind you.', '2011-04-18 11:59:20.000000', NULL, 0),
(6389379, 945523, 103142, '<td valign="top">awesome finish! This shot is so cool... I just love the textures.  Personally, I like it better than Bear''s :D<br/> <br/></td>', 'awesome finish! This shot is so cool... I just love the textures.  Personally, I like it better than Bear''s :D ', '2011-04-18 11:59:21.000000', NULL, 0),
(6389399, 945725, 11960, '<td valign="top">Awesome! Literally laughing.</td>', 'Awesome! Literally laughing.', '2011-04-18 12:28:00.000000', NULL, 0),
(6389404, 945725, 24454, '<td valign="top">I love it when superhuman efforts get rewarded with first prize! This is so brilliantly creative and amazing!  Congratulations on flawless, award-winning execution!<br/> <br/></td>', 'I love it when superhuman efforts get rewarded with first prize! This is so brilliantly creative and amazing!  Congratulations on flawless, award-winning execution! ', '2011-04-18 12:36:13.000000', NULL, 0),
